INSERT INTO `issue` VALUES (1,2,1,1,'',0,'docs(readme): fix docs links to work in gitea','',0,0,1,1,0,'',0,0,1713866118,1713866138,1713866138,0),(2,2,2,1,'',0,'docs(readme): add 10GbE switch to LAN','',0,0,1,1,0,'',0,0,1713866378,1713866384,1713866384,0),(3,2,3,1,'',0,'feat: gitea','This PR adds MySQL and Gitea.\r\n\r\nIt also includes K3s \"storers\" and some random fixes because I am bad at git.',0,0,1,1,0,'',0,0,1713983732,1713983786,1713983786,0),(4,2,4,1,'',0,'feat(playbook): add ArgoCD','',0,0,1,1,1,'',0,0,1713983838,1715333377,1715333375,0),(5,2,5,1,'',0,'feat(playbook): k3s patch playbook','',0,0,1,1,0,'',0,0,1714572571,1714572582,1714572581,0),(6,2,6,1,'',0,'WIP: feat/ingress','',0,0,0,1,0,'',0,0,1714572595,1714572595,0,0),(7,3,1,1,'',0,'feat(app): sealed-secrets','',0,0,1,1,0,'',0,0,1715334431,1715334444,1715334438,0),(8,2,7,1,'',0,'feat(app): FreshRSS','',0,0,1,1,0,'',0,0,1716743282,1730640604,1730640601,0),(9,2,8,1,'',0,'fix: increase CPU and RAM','',0,0,1,1,0,'',0,0,1727005694,1727005708,1727005700,0),(10,2,9,1,'',0,'feat/remove-storers','TechoTim removed the storers and I have eventually decideed to do the same. \r\n\r\nOriginally I didn\'t want the worker node to crash and ruin the ability to access the local storage but instead I will make sure nodes don\'t crash.',0,0,1,1,0,'',0,0,1727006389,1727006398,1727006395,0),(11,2,10,1,'',0,'fix: remove storers mention in playbook','',0,0,1,1,0,'',0,0,1727006956,1727006961,1727006959,0),(12,2,11,1,'',0,'chore(deps): update K3s from 1.27 to 1.31','BREAKING CHANGE: I am destroying and rebuilding.',0,0,1,1,0,'',0,0,1727007057,1727007062,1727007060,0),(13,3,2,1,'',0,'feat: move mealie to its own namespace','',0,0,1,1,0,'',0,0,1727012515,1727012523,1727012521,0),(14,3,3,1,'',0,'feat: use token for gitea access instead of cert','',0,0,1,1,0,'',0,0,1727012531,1727012535,1727012533,0),(15,3,4,1,'',0,'feat: sync waves','',0,0,1,1,0,'',0,0,1727012542,1727012547,1727012545,0),(16,3,5,1,'',0,'fix: sync-waves, sealed secrets required first','',0,0,1,1,0,'',0,0,1727013065,1727013068,1727013068,0),(17,3,6,1,'',0,'chore(deps): selaed secrets','',0,0,1,1,0,'',0,0,1727014630,1727014633,1727014632,0),(18,3,7,1,'',0,'fix: argocd not needing early sync waves','',0,0,1,1,0,'',0,0,1727014964,1727014968,1727014966,0),(19,3,8,1,'',0,'fix: homepage-api-tokens-secret','',0,0,1,1,0,'',0,0,1727014979,1727014984,1727014982,0),(20,3,9,1,'',0,'fix: mealie namespace missing','',0,0,1,1,0,'',0,0,1727017763,1727017768,1727017766,0),(21,2,12,1,'',0,'feat: PostgreSQL','',0,0,1,1,0,'',0,0,1727050161,1727050174,1727050173,0),(22,2,13,1,'',0,'WIP: feat: Longhorn','',0,0,0,1,0,'',0,0,1727303009,1731156811,0,0),(23,2,14,1,'',0,'docs(readme): deleted all apps from NAS and installed Kubernetes onto NUC','',0,0,1,1,0,'',0,0,1730565439,1730565451,1730565448,0),(24,2,15,1,'',0,'docs(readme): mention Minio installed onto NAS','',0,0,1,1,0,'',0,0,1730565670,1730565761,1730565755,0),(25,2,16,1,'',0,'feat: increase cores of K3s nodes','increase cores available to K3s nodes from 4 to 8, seems to behave a little smoother now.',0,0,1,1,0,'',0,0,1730642458,1730642468,1730642461,0),(26,2,17,1,'',0,'chore: update K3s playbook','',0,0,1,1,0,'',0,0,1730663507,1730663693,1730663692,0),(27,2,18,1,'',0,'chore: more updates for K3s','',0,0,1,1,0,'',0,0,1730663816,1730663823,1730663819,0),(28,2,19,1,'',0,'chore: update K3s playbook','',0,0,1,1,0,'',0,0,1730665412,1730665436,1730665433,0),(29,2,20,1,'',0,'fix: default settings from K3s playbook update','',0,0,1,1,0,'',0,0,1730667005,1730667009,1730667007,0),(30,3,10,1,'',0,'feat: traefik-3','',0,0,1,1,0,'',0,0,1730758323,1730759137,1730759136,0),(31,2,21,1,'',0,'style: main.tf','',0,0,1,1,0,'',0,0,1730842736,1730842748,1730842746,0),(32,2,22,1,'',0,'feat: use S3 for .tfstate','',0,0,1,1,0,'',0,0,1730842955,1730843105,1730843103,0),(33,2,23,1,'',0,'feat: S3','',0,0,1,1,0,'',0,0,1730849995,1730850046,1730850046,0);
